export function isLuhnValid(text) {
    const s = text.replace(/ /g, '');
    if (s.length < 2 || !/^[0-9]+$/.test(s))
        return false;
    let sum = 0, doubled = false;
    for (let i = s.length - 1; i >= 0; i--) {
        let d = Number(s[i]);
        if (doubled) {
            d *= 2;
            if (d > 9)
                d -= 9;
        }
        sum += d;
        doubled = !doubled;
    }
    return sum % 10 === 0;
}
